// Oeste Banner — Mesa theme (v0.2.0).
// Copy-paste ready. Requires: React 18+, Tailwind with dark: variant, JSX transform.
// Requires Mesa tokens: import src/tokens.css once (or copy src/tokens.json).
// Source: https://github.com/eric2busy/Oeste/blob/main/mesa/src/index.js
// Docs: https://oeste.hiddeninwest.com/mesa/#/components/banner

export function Banner({ children }) {
  return (
    <div className="bg-[#181b1f] px-5 py-[9px] text-center text-[12.5px] tracking-[0.02em] text-[#f3efe6] dark:border-b dark:border-[#2e2720] dark:bg-[#060504] dark:text-[#e8dfc9] [&_strong]:font-bold">
      {children}
    </div>
  );
}
